import DataTable from '../components/DataTable.vue'
import AppModal from '../components/AppModal.vue'
import DynamicForm from '../components/DynamicForm.vue'
import { request } from '../api'

function notify(message, type = 'error') { window.dispatchEvent(new CustomEvent('polaris:toast', { detail: { message, type } })) }

const route = useRoute(); const router = useRouter()
const alias = { receipt: 'inbound', barcode: 'barcode' }
const tab = ref(alias[route.params.tab] || route.params.tab || 'overview')
const tabs = [{ key: 'overview', label: '仓储总览' }, { key: 'inbound', label: '收料 / 上架 / 退料' }, { key: 'outbound', label: '领料 / 出库 / 报废' }, { key: 'transfer', label: '调拨 / 移库' }, { key: 'count', label: '盘点与差异' }, { key: 'inventory', label: '库存与批次' }, { key: 'trace', label: '批次追溯' }, { key: 'barcode', label: '条码管理' }, { key: 'master', label: '仓库主数据' }, { key: 'transactions', label: '事务流水' }, { key: 'documents', label: '仓储单据' }]
