const inboundTypes = [{ value: 'RECEIPT', label: '采购收料', icon: '⇩', description: '供应商 / 委外到货' }, { value: 'PUTAWAY', label: '合格上架', icon: '⌂', description: '待检转合格库位' }, { value: 'RETURN', label: '生产退料', icon: '↩', description: '退回原材料库存' }, { value: 'FINISHED_RECEIPT', label: '成品入库', icon: '▣', description: '完工产品入库' }]
const outboundTypes = [{ value: 'ISSUE', label: '生产领料', icon: '⇧', description: '按工单发料 / 超领' }, { value: 'SALES_OUTBOUND', label: '销售出库', icon: '➜', description: '按销售单发货' }, { value: 'SCRAP', label: '报废出库', icon: '×', description: '登记报废原因' }]
const summary = ref({}); const inventory = ref([]); const transactions = ref([]); const documents = ref([]); const documentLines = ref([]); const barcodes = ref([]); const warehouses = ref([]); const locations = ref([]); const materials = ref([]); const counts = ref([]); const countLines = ref([]); const batches = ref([])
const inventoryKeyword = ref(''); const inventoryStatus = ref(''); const transactionKeyword = ref(''); const transactionType = ref(''); const documentType = ref(''); const documentStatus = ref(''); const barcodeKeyword = ref(''); const barcodeStatus = ref(''); const traceResult = ref([]); const selectedCount = ref(null); const selectedDocument = ref(null); const showTransaction = ref(false); const showMaster = ref(false); const showDocument = ref(false)
const form = ref({ transactionType: 'RECEIPT', materialCode: '', materialName: '', warehouseCode: '', locationCode: '', fromLocationCode: '', toLocationCode: '', quantity: '', unit: '件', batchNo: '', sourceDocNo: '', remark: '' })
const transfer = ref({ materialCode: '', batchNo: '', quantity: '', unit: '件', fromWarehouseCode: '', fromLocationCode: '', toWarehouseCode: '', toLocationCode: '' })
const traceForm = ref({ materialCode: '', batchNo: '', barcode: '' }); const masterForm = ref({ type: 'warehouse', warehouseCode: '', warehouseName: '', locationCode: '', locationName: '', materialCode: '', materialName: '', unit: '件' })
