  ...(masterForm.value.type === 'material' ? [{ key: 'materialCode', label: '物料编码', required: true }, { key: 'materialName', label: '物料名称', required: true }, { key: 'unit', label: '单位', placeholder: '件' }] : [])
])
const transactionColumns = [{ key: 'transaction_no', label: '事务单号' }, { key: 'transaction_type', label: '类型', format: transactionLabel }, { key: 'material_code', label: '物料编码' }, { key: 'warehouse_code', label: '仓库' }, { key: 'location_code', label: '库位' }, { key: 'quantity', label: '数量', format: (value, row) => `${value} ${row.unit || ''}` }, { key: 'operator_name', label: '操作人' }, { key: 'created_at', label: '时间' }]
const inventoryColumns = [{ key: 'material_code', label: '物料编码' }, { key: 'material_name', label: '物料名称' }, { key: 'warehouse_code', label: '仓库' }, { key: 'location_code', label: '库位' }, { key: 'batch_no', label: '批次' }, { key: 'available_qty', label: '可用', format: (value, row) => `${value} ${row.unit || ''}` }, { key: 'locked_qty', label: '锁定' }, { key: 'reserved_qty', label: '预留' }, { key: 'stock_status', label: '状态', status: true, format: value => ({ AVAILABLE: '可用', FROZEN: '冻结', HOLD: '隔离' }[value] || value) }]
const countColumns = [{ key: 'count_no', label: '盘点单号' }, { key: 'count_type', label: '类型' }, { key: 'warehouse_code', label: '仓库' }, { key: 'location_code', label: '库位' }, { key: 'operator_name', label: '操作人' }, { key: 'status', label: '状态', status: true, format: value => value === 'OPEN' ? '待盘点' : '已提交' }, { key: 'created_at', label: '创建时间' }]
const traceColumns = [{ key: 'transaction_no', label: '事务单号' }, { key: 'transaction_type', label: '类型', format: transactionLabel }, { key: 'material_code', label: '物料' }, { key: 'batch_no', label: '批次' }, { key: 'quantity', label: '数量' }, { key: 'source_doc_no', label: '来源单号' }, { key: 'operator_name', label: '操作人' }, { key: 'created_at', label: '时间' }]
const barcodeColumns = [{ key: 'barcode', label: '条码' }, { key: 'barcode_type', label: '类型' }, { key: 'material_code', label: '物料编码' }, { key: 'batch_no', label: '批次' }, { key: 'location_code', label: '库位' }, { key: 'status', label: '状态', status: true, format: value => value === 'ACTIVE' ? '有效' : '已作废' }, { key: 'printed_count', label: '打印次数' }]
const documentColumns = [{ key: 'document_no', label: '单据号' }, { key: 'document_type', label: '单据类型', format: documentTypeLabel }, { key: 'warehouse_code', label: '仓库' }, { key: 'source_doc_no', label: '来源单号' }, { key: 'operator_name', label: '操作人' }, { key: 'status', label: '状态', status: true, format: documentStatusLabel }, { key: 'created_at', label: '创建时间' }]
const filteredInventory = computed(() => inventory.value.filter(item => (!inventoryKeyword.value || `${item.material_code}${item.material_name}${item.batch_no}${item.location_code}`.toLowerCase().includes(inventoryKeyword.value.toLowerCase())) && (!inventoryStatus.value || item.stock_status === inventoryStatus.value)))
const filteredTransactions = computed(() => transactions.value.filter(item => (!transactionType.value || item.transaction_type === transactionType.value) && (!transactionKeyword.value || `${item.transaction_no}${item.material_code}${item.source_doc_no || ''}`.toLowerCase().includes(transactionKeyword.value.toLowerCase()))))
const transferTransactions = computed(() => transactions.value.filter(item => ['MOVE', 'TRANSFER_OUT', 'TRANSFER_IN'].includes(item.transaction_type)))
const totalQty = computed(() => inventory.value.reduce((sum, item) => sum + Number(item.available_qty || 0) + Number(item.locked_qty || 0), 0)); const availableQty = computed(() => inventory.value.reduce((sum, item) => sum + Number(item.available_qty || 0), 0)); const lockedQty = computed(() => inventory.value.reduce((sum, item) => sum + Number(item.locked_qty || 0), 0)); const reservedQty = computed(() => inventory.value.reduce((sum, item) => sum + Number(item.reserved_qty || 0), 0)); const lowStockCount = computed(() => inventory.value.filter(item => Number(item.available_qty || 0) < Number(item.safety_stock || 0)).length)

function transactionLabel(value) { return transactionTypes.find(item => item.value === value)?.label || ({ LOCK: '库存锁定', UNLOCK: '库存解锁', ADJUSTMENT: '盘点调整' }[value] || value) }
function documentTypeLabel(value) { return transactionLabel(value) || value || '-' }
function documentStatusLabel(value) { return ({ COMPLETED: '已完成', OPEN: '待处理', CANCELLED: '已取消' }[value] || value || '-') }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }
function switchTab(value) { tab.value = value; router.push(`/warehouse/${value}`); if (value !== 'trace') traceResult.value = []; load() }
function openTransaction(type, row = {}) { form.value = { transactionType: type, materialCode: row.material_code || '', materialName: row.material_name || '', warehouseCode: row.warehouse_code || warehouses.value[0]?.warehouse_code || '', locationCode: row.location_code || locations.value[0]?.location_code || '', fromLocationCode: type === 'MOVE' ? row.location_code || '' : '', toLocationCode: '', quantity: '', unit: row.unit || '件', batchNo: row.batch_no || '', sourceDocNo: '', remark: '' }; showTransaction.value = true }
async function load() { try { const [s, i, t, d, b, w, l, m, c, bt] = await Promise.all([request('/warehouse/summary'), request(`/warehouse/inventory?keyword=${encodeURIComponent(inventoryKeyword.value)}&stockStatus=${encodeURIComponent(inventoryStatus.value)}`), request(`/warehouse/transactions?keyword=${encodeURIComponent(transactionKeyword.value)}&type=${encodeURIComponent(transactionType.value)}&limit=200`), request(`/warehouse/documents?type=${encodeURIComponent(documentType.value)}&status=${encodeURIComponent(documentStatus.value)}`), request(`/warehouse/barcodes?keyword=${encodeURIComponent(barcodeKeyword.value)}&status=${encodeURIComponent(barcodeStatus.value)}`), request('/warehouse/warehouses'), request('/warehouse/locations'), request('/warehouse/materials'), request('/warehouse/counts'), request('/warehouse/batches')]); summary.value = s || {}; inventory.value = i || []; transactions.value = t || []; documents.value = d || []; barcodes.value = b || []; warehouses.value = w || []; locations.value = l || []; materials.value = m || []; counts.value = c || []; batches.value = bt || []; if (!transfer.value.fromWarehouseCode) { transfer.value.fromWarehouseCode = warehouses.value[0]?.warehouse_code || ''; transfer.value.toWarehouseCode = warehouses.value[0]?.warehouse_code || ''; transfer.value.fromLocationCode = locations.value[0]?.location_code || ''; transfer.value.toLocationCode = locations.value[1]?.location_code || locations.value[0]?.location_code || '' } } catch (error) { notify(error.message) } }
async function saveTransaction() { try { await request('/warehouse/transactions', { method: 'POST', body: JSON.stringify(form.value) }); showTransaction.value = false; await load() } catch (error) { notify(error.message) } }
async function saveTransfer() { try { await request('/warehouse/transactions', { method: 'POST', body: JSON.stringify({ ...transfer.value, transactionType: 'MOVE', warehouseCode: transfer.value.toWarehouseCode, locationCode: transfer.value.toLocationCode }) }); notify('调拨已提交', 'success'); await load() } catch (error) { notify(error.message) } }
async function createCount() { try { const result = await request('/warehouse/counts', { method: 'POST', body: JSON.stringify({ warehouseCode: warehouses.value[0]?.warehouse_code || '', countType: 'CYCLE' }) }); await load(); await openCount({ id: result.id, count_no: result.countNo, status: 'OPEN', warehouse_code: warehouses.value[0]?.warehouse_code }) } catch (error) { notify(error.message) } }
async function openCount(row) { selectedCount.value = row; try { countLines.value = await request(`/warehouse/counts/${row.id}/lines`) } catch (error) { notify(error.message) } }
async function openDocument(row) { selectedDocument.value = row; try { documentLines.value = await request(`/warehouse/documents/${row.id}/lines`); showDocument.value = true } catch (error) { notify(error.message) } }
async function submitCount() { try { await request(`/warehouse/counts/${selectedCount.value.id}/submit`, { method: 'POST', body: JSON.stringify({ lines: countLines.value.map(line => ({ id: line.id, countQty: Number(line.count_qty || 0), reasonCode: 'COUNT' })) }) }); selectedCount.value = null; countLines.value = []; await load() } catch (error) { notify(error.message) } }
async function searchTrace() { try { traceResult.value = await request(`/warehouse/trace?materialCode=${encodeURIComponent(traceForm.value.materialCode)}&batchNo=${encodeURIComponent(traceForm.value.batchNo)}&barcode=${encodeURIComponent(traceForm.value.barcode)}`) } catch (error) { notify(error.message) } }
function openTrace(row) { traceForm.value = { materialCode: row.material_code, batchNo: row.batch_no || '', barcode: '' }; tab.value = 'trace'; router.push('/warehouse/trace'); searchTrace() }
async function searchBarcode(code) { traceForm.value = { materialCode: '', batchNo: '', barcode: code }; tab.value = 'trace'; router.push('/warehouse/trace'); await searchTrace() }
async function createBarcode() { try { await request('/warehouse/barcodes', { method: 'POST', body: JSON.stringify({ ruleCode: 'MATERIAL', barcodeType: 'MATERIAL', materialCode: materials.value[0]?.material_code || '' }) }); await load() } catch (error) { notify(error.message) } }
async function printSelected() { const active = barcodes.value.filter(item => item.status === 'ACTIVE').slice(0, 1).map(item => item.barcode); if (!active.length) return notify('没有可打印的有效条码'); try { await request('/warehouse/barcodes/print', { method: 'POST', body: JSON.stringify({ barcodes: active }) }); await load() } catch (error) { notify(error.message) } }
async function voidBarcode(row) { if (!window.confirm(`确认作废条码 ${row.barcode}？`)) return; try { await request(`/warehouse/barcodes/${encodeURIComponent(row.barcode)}/void`, { method: 'POST' }); await load() } catch (error) { notify(error.message) } }
async function openLock(row) { const quantity = Number(window.prompt(`请输入锁定数量（可用 ${row.available_qty} ${row.unit || ''}）`, '1')); if (!Number.isInteger(quantity) || quantity <= 0) return; try { await request('/warehouse/lock', { method: 'POST', body: JSON.stringify({ materialCode: row.material_code, warehouseCode: row.warehouse_code, locationCode: row.location_code, batchNo: row.batch_no, quantity }) }); await load() } catch (error) { notify(error.message) } }
async function toggleFreeze(row) { const freeze = row.stock_status !== 'FROZEN'; if (freeze && !window.confirm(`确认冻结 ${row.material_code} / ${row.batch_no || '无批次'}？`)) return; try { await request(`/warehouse/${freeze ? 'freeze' : 'unfreeze'}`, { method: 'POST', body: JSON.stringify({ materialCode: row.material_code, warehouseCode: row.warehouse_code, locationCode: row.location_code, batchNo: row.batch_no, reasonCode: 'WEB' }) }); await load() } catch (error) { notify(error.message) } }
async function saveMaster() { try { const type = masterForm.value.type; const path = type === 'warehouse' ? '/warehouse/masters/warehouses' : type === 'location' ? '/warehouse/masters/locations' : '/warehouse/masters/materials'; await request(path, { method: 'POST', body: JSON.stringify(masterForm.value) }); showMaster.value = false; await load() } catch (error) { notify(error.message) } }
onMounted(load)
</script>

