ding:11px 0;font-size:10px;color:#718396}.count-line b,.count-line small{display:block}.count-line b{color:#425d75}.count-line small{color:#9aa9b7;margin-top:4px}.count-line input{width:100%}.count-line em{font-style:normal}.count-line .positive{color:#2aa773}.count-line .negative{color:#db765d}.trace-search{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px;margin-bottom:18px}.trace-summary{display:flex;align-items:baseline;gap:7px;margin-bottom:10px;color:#91a0ad;font-size:10px}.trace-summary b{font-size:24px;color:#2d5f98}.master-columns{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.master-columns>div{border:1px solid #e7edf3;border-radius:8px;padding:14px}.master-columns h4{font-size:12px;color:#3f5971;margin:0 0 9px}.master-row{border-top:1px solid #edf2f6;padding:10px 0}.master-row b,.master-row small{display:block}.master-row b{font-size:11px;color:#526b80}.master-row small{font-size:9px;color:#98a8b6;margin-top:3px}@media(min-width:1500px){.transfer-panel .inline-form-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:900px){.operation-cards,.master-columns{grid-template-columns:repeat(2,1fr)}.inline-form-grid{grid-template-columns:repeat(2,1fr)}.trace-search{grid-template-columns:1fr 1fr}.warehouse-flow{flex-wrap:wrap;gap:7px}}@media(max-width:600px){.operation-cards,.master-columns,.inline-form-grid{grid-template-columns:1fr}.count-line{grid-template-columns:1.2fr .7fr 80px}.count-line strong,.count-line em{grid-column:auto}.trace-search{grid-template-columns:1fr}.warehouse-stats{grid-template-columns:repeat(2,1fr);row-gap:12px}}
.transfer-panel .section-title-spaced h3{margin:0;font-size:16px;color:#203b56}
